    },
    "philosophy": {
      "type": "editorial-text",
      "settings": {
        "eyebrow": "Philosophy",
        "heading": "LUXURY, WITHOUT THE LOGO",
        "text": "<p>Some pieces speak for themselves.</p><p>In the curve of a handle, the warmth of leather, and the way a bag becomes part of your day.<br>Velantra is a collection for that feeling. Beautiful to carry. Entirely your own.</p>"
      }
    },
    "triptych": {
      "type": "featured-model-collection",
      "settings": {
        "heading": "THE SIGNATURE COLLECTION",
        "eyebrow": "",
        "show_collection_link": true,
        "show_prices": true,
        "ratio": "4/5",
        "columns": 3,
        "gap": 12,
        "mobile_layout": "scroll",
        "side_padding": 6,
        "vertical_padding": 0
      },
      "blocks": {
        "vivienne": {
          "type": "product",
          "settings": {
