      "type": "editorial-text",
      "settings": {
        "eyebrow": "The edit",
        "heading": "WELL CARRIED",
        "text": "<p>For the everyday, and the days you remember.</p>",
        "label": "Explore the collection",
        "link": "/collections/handbags"
      }
