    "wide": {
      "type": "image-gallery",
      "settings": {
        "columns": 1,
        "ratio": "21/9",
        "gap": 0,
        "padding": 0
      },
      "blocks": {
        "image": {
          "type": "image",
          "settings": {
            "default_asset": "vivienne-studio-wide.jpg",
            "alt": "The Vivienne in the studio",
            "link": "/products/velantra-vivienne"
          }
        }
