{
  "sections": {
    "main": {
      "type": "main-product",
      "settings": {
        "title_override": "COLETTE",
        "description_override": "<p>The Colette belongs to crisp mornings, long lunches and the coat you return to every autumn. A softly structured brushed-wool body meets smooth leather at the handles and belted front, with warm gold details catching the light. Tactile and quietly expressive, it brings a little softness to a full day.</p><p>The character begins with contrast: a short, matte wool nap against smooth leather-wrapped handle arcs. Tonal seams follow the body, while the curved belt ends finish in small gold-tone caps. Each texture has room to be felt and seen.</p>",
        "fact_material": "Brushed wool; vegetable-tanned leather trim",
        "fact_detail": "Made by artisans with 10 years of experience",
        "preorder_lead_time": "10 days before dispatch",
        "show_facts": true,
        "show_policies": false,
        "show_shipping_summary": false,
        "fact_carry": "10 days before dispatch",
        "lead_time": "10 days before dispatch"
