        "tab_care": {
          "type": "accordion",
          "settings": {
            "heading": "Care",
            "content": "<p>Brush the wool gently with a soft garment brush, following the nap. Spot-clean with a barely damp cloth and let it dry naturally. Wipe the leather trim with a dry cloth and store the bag away from direct heat and sunlight.</p>",
            "open": false
          }
        },
        "tab_shipping": {
